func (c *Client) Comments() *CommentsService {
	return NewCommentsService(c)
}

// Pages returns a builder for the pages resource.
func (c *Client) Pages() *PagesService {
	return NewPagesService(c)
}

// Posts returns a builder for the posts resource.
func (c *Client) Posts() *PostsService {
	return NewPostsService(c)
}

// Users returns a builder for the users resource.
func (c *Client) Users() *UsersService {
	return NewUsersService(c)
}

// BlogUserInfos returns a builder for the blogUserInfos resource.
func (c *Client) BlogUserInfos() *BlogUserInfosService {
	return NewBlogUserInfosService(c)
